#include <iostream>
#include <vector>
using namespace std;

int main() {
    int N;
    cin >> N;

    vector<int> A(N);
    for (int& a : A) {
        cin >> a;
    }

    // 残ることが確定したカードの合計
    int answer = 0;
    // 全部確定するまで操作を行う
    while (!A.empty()) {
        int a = A.back();
        A.pop_back();

        bool found = false; // 同じカードがあるか
        for (int i = 0; i < A.size(); ++i) {
            if (A[i] == a) { // 同じカードがあったら
                A.erase(begin(A) + i); // A から消す
                found = true;
                break;
            }
        }
        if (!found) { // 同じカードがなければ
            answer += a; // 合計に足す
        }
    }

    cout << answer << endl;
    return 0;
}
